export interface BaseHighlightOptions extends AnimOptions {
    /** Primary accent color. Defaults to vibrant gold (0xfacc15) or context accent. */
    color?: Color;

    /** Bounding padding around target. Scalar or [padX, padY]. Defaults to 0.2. */
    padding?: number | [number, number];

    /** If true, highlight remains in scene after animation finishes. Defaults to false. */
    persist?: boolean;
}

import { Circumscribe } from "retiam/highlights";
import { Color } from "retiam";

// Rectangle highlight
await scene.play(new Circumscribe(titleText));

// Pill highlight around code token with custom gold accent
await scene.play(new Circumscribe(token, {
    shape: "pill",
    color: Color.fromHex(0xffd700),
    padding: [0.3, 0.15],
    duration: 1200
}));

